<html>
<head>
  <title>Random Joke Website</title>
</head>
<body>
  <h1>Random Joke Website</h1>
  <button id="button">Click me!</button>
  <script>
    // Define an array of jokes
    const jokes = [
      "Why don't scientists trust atoms? Because they make up everything.",
      "I told my wife she was drawing her eyebrows too high. She looked surprised.",
      "Why don't lobsters share? Because they're shellfish.",
      "What do you call a fake noodle? An impasta."
    ];

    // Function to generate a random joke
    function getRandomJoke() {
      // Get a random number between 0 and the length of the array - 1
      const randomNumber = Math.floor(Math.random() * jokes.length);
      // Return the joke at the selected position
      return jokes[randomNumber];
    }

    // Add an event listener to the button
    document.getElementById("button").addEventListener("click", getRandomJoke);
  </script>
</body>
</html>
```
